CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), email TEXT NOT NULL UNIQUE, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, email_verified BOOLEAN NOT NULL DEFAULT FALSE, status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','suspended','deleted')), created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS service_catalog (service_key TEXT PRIMARY KEY, display_name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', api_version TEXT NOT NULL DEFAULT 'v1', enabled BOOLEAN NOT NULL DEFAULT TRUE, sort_order INTEGER NOT NULL DEFAULT 100, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS refresh_sessions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash TEXT NOT NULL UNIQUE, expires_at TIMESTAMPTZ NOT NULL, revoked_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
INSERT INTO service_catalog(service_key,display_name,description,sort_order) VALUES ('account','My Account','Identity, profile and session management',10),('cloud','My Cloud','User storage and synchronized launcher data',20),('mod-hub','My Mod Hub','Mod and modpack discovery integrations',30),('download','My Download','Managed downloads and update delivery',40),('security','My Security','Security status and account protection',50),('profile','My Profile','Player profile and skin metadata',60),('performance','My Performance','Launcher diagnostics and performance settings',70),('news','My News','Announcements and release notes',80),('update','My Update','Launcher update metadata and channels',90),('support','My Support','Support requests and issue tracking',100) ON CONFLICT(service_key) DO NOTHING;
